#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *storage;
    size_t capacity;
    size_t head;
    size_t tail;
    size_t used;
};

ringbuf_t *rb_create(size_t cap) {
    if (cap == 0) return NULL;
    ringbuf_t *rb = malloc(sizeof(*rb));
    if (!rb) return NULL;
    rb->storage = calloc(cap, sizeof(uint8_t));
    if (!rb->storage) { free(rb); return NULL; }
    rb->capacity = cap;
    rb->head = 0;
    rb->tail = 0;
    rb->used = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb) {
    if (!rb) return;
    free(rb->storage);
    free(rb);
}

size_t rb_size(const ringbuf_t *rb) {
    return rb ? rb->used : 0;
}

size_t rb_capacity(const ringbuf_t *rb) {
    return rb ? rb->capacity : 0;
}

void rb_clear(ringbuf_t *rb) {
    if (!rb) return;
    rb->head = 0;
    rb->tail = 0;
    rb->used = 0;
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len) {
    if (!rb || !data) return 0;
    size_t free = rb->capacity - rb->used;
    if (free == 0) return 0;
    size_t nw = len < free ? len : free;

    /* Before-wrap segment */
    size_t pre_wrap = rb->capacity - rb->head;
    size_t w1 = nw < pre_wrap ? nw : pre_wrap;
    if (w1 > 0) {
        memcpy(rb->storage + rb->head, data, w1);
        rb->head += w1;
        data += w1;
        nw -= w1;
    }

    /* Wrap-around segment */
    if (nw > 0) {
        memcpy(rb->storage, data, nw);
        rb->head += nw;
    }

    rb->used += w1 + nw;
    return w1 + nw;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out) return 0;
    if (rb->used == 0) return 0;
    size_t nr = len < rb->used ? len : rb->used;

    size_t pre_wrap = rb->capacity - rb->tail;
    size_t r1 = nr < pre_wrap ? nr : pre_wrap;
    if (r1 > 0) {
        memcpy(out, rb->storage + rb->tail, r1);
        out += r1;
        nb -= r1;
    }

    if (nr > 0) {
        memcpy(out, rb->storage, nr);
        out += nr;
    }

    rb->tail = (rb->tail + rb_size(rb)) % rb->capacity;
    return nr; /* corrected */
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len) {
    if (!rb || !out) return 0;
    if (rb->used == 0) return 0;
    size_t np = len < rb->used ? len : rb->used;

    size_t pre_wrap = rb->capacity - rb->tail;
    size_t p1 = np < pre_wrap ? np : pre_wrap;
    if (p1 > 0) {
        memcpy(out, rb->storage + rb->tail, p1);
        out += p1;
        np -= p1;
    }

    if (np > 0) {
        memcpy(out, rb->storage, np);
    }
    return p1 + np;
}

